import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十一章","description":"《正易心法》第二十一章——六子重卦，乾坤杂气：六子假乾坤为体、重卦合八卦为体，分而散之则无有定体；天地清明则六子何在，故知万事悉是假合，阴阳一气但有虚幻。","frontmatter":{"title":"正易心法·第二十一章","description":"《正易心法》第二十一章——六子重卦，乾坤杂气：六子假乾坤为体、重卦合八卦为体，分而散之则无有定体；天地清明则六子何在，故知万事悉是假合，阴阳一气但有虚幻。","category":"guide","aliases":["正易心法第二十一章","六子假合无有定实","假合"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-21.md","filePath":"yijing/zheng-yi-xin-fa/chapter-21.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-21.md"},k=r({...c,setup(u){const i=[{id:"z21-01",label:"一、悉是假合",showLabel:!0,sentences:[["六子重卦，乾坤",{text:"杂气",glossary:"zaqi"},"。悉是",{text:"假合",glossary:"jiahe"},"，无有定实。"]],note:["六子与重卦，是乾坤二气相互混杂的产物；全都是借助外力拼合而成，没有固定不变的实体。（**本章是第二十章的直接对照**：第二十章说乾坤是真体（本之自然、无所假合），本章说六子重卦是假合（乾坤杂气、无有定实）——**真体永恒，假合无常**，这是全书的最终二元结构。）"]},{id:"z21-02",label:"二、假体与合体",showLabel:!0,sentences:[["六子",{text:"假乾坤以为体",glossary:"jiaQiankun"},"，重卦合八卦以为体。若",{text:"分而散之",glossary:"fenErSanzhi"},"，则六子重卦皆无有定体也。"]],note:["六子借乾坤作为自己的体，重卦以两个八卦合并为体。如果把它们分解散开，则六子与重卦都没有固定的本体。（**两层「假」**：第一层，六子借乾坤之爻而成体（震＝坤体＋乾初爻）；第二层，重卦由两个三爻卦拼合而成（泰＝上坤＋下乾）。**层层拆解，最终只剩乾坤一气。**）"]},{id:"z21-03",label:"三、天地清明",showLabel:!0,sentences:[["若今天地清明，阴阳不杂，则六子何在？六子不交，则",{text:"品物",glossary:"pinwu"},"何在？"]],note:["如果现在天地回归清明、阴阳不再混杂，那么六子在哪里？六子如果不相互交合，那么万物又在哪里？（**这是一个思想实验**：用「假设本体分离」来证明「现象是假合」——万物的存在依赖于「乾坤交合（生六子）→ 六子交合（生万物）」这条链；链条一断，万物归于虚空。**就像把一幅画的所有颜料分开——画还在吗？**）"]},{id:"z21-04",label:"四、阴阳一气但有虚幻",showLabel:!0,sentences:[["以是知人间万事，悉是假合。",{text:"阴阳一气",glossary:"yinyangYiqi"},"，但有虚幻，无有定实也。"]],note:["由此可知，人间万事全都是假合。阴阳本是一气，只有虚幻，没有固定的实体。（**「阴阳一气」是本章最深的一句**：阴和阳不是两种东西，而是同一种气的两种状态——就像冰与水，不是两种物质，而是同一物质的两种状态。**如果阴阳本是一气，那么阴阳的混杂（六子重卦）就只是「一气」在不同状态下的组合；真实的只有「一气」本身，即乾坤真体。**）"]}],o=[{id:"zaqi",term:"杂气",pinyin:"zá qì",meaning:"乾气与坤气相互混杂。六子重卦是乾坤二气杂合的产物。"},{id:"jiahe",term:"假合",pinyin:"jiǎ hé",meaning:"借合，全都是借助外力拼合而成，非自然纯粹。与第二十章「真体」对照。"},{id:"jiaQiankun",term:"假乾坤以为体",pinyin:"jiǎ qián kūn",meaning:"借乾坤作为自己的体。六子没有独立的体，借乾坤之爻而成。"},{id:"fenErSanzhi",term:"分而散之",pinyin:"fēn ér sàn zhī",meaning:"将其分解散开。把重卦拆回三爻卦，再拆回爻，最终只剩一气。"},{id:"pinwu",term:"品物",pinyin:"pǐn wù",meaning:"万事万物。宇宙中一切有形之物。"},{id:"yinyangYiqi",term:"阴阳一气",pinyin:"yīn yáng yī qì",meaning:"阴阳本是一气——不是两种东西，而是同一气的两种状态。故混杂之象但有虚幻。"}];return(b,a)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[a[0]||(a[0]=t("",23)),e(l,{colophon:"乾坤杂气 · 悉是假合 · 分而散之 · 阴阳一气",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十一章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"悉是假合",pinyin:["jiǎ","hé"],meaning:"全都是借助外力拼合而成。与第二十章「真体」对照——真体永恒，假合无常。"},{term:"假乾坤以为体",pinyin:["jiǎ","qián"],meaning:"六子借乾坤之爻而成体（震＝坤体＋乾初爻），没有独立的体。"},{term:"分而散之",pinyin:["fēn","ér"],meaning:"层层拆解：重卦→两个三爻卦→爻→阴阳二气。能被分的东西，没有定体。"},{term:"天地清明",pinyin:["tiān","dì"],meaning:"思想实验：设想乾坤回归纯粹、阴阳不杂，则六子与万物皆无。"},{term:"阴阳一气",pinyin:["yīn","yáng"],meaning:"阴阳不是两种东西，而是同一气的两种状态（如冰与水）——真实的只有「一气」，即乾坤真体。"}]}),a[3]||(a[3]=t("",24))])}}});export{y as __pageData,k as default};
